/** Reusable document, drawable and diagnostics samples. */
export function createAdvancedScenes(S){
 const colors=['#30DEAB','#7297FF','#FFBC67','#D38BFA'];
 function run(fn){return(c,w,h,o={})=>{const owned=[];const own=x=>(owned.push(x),x);const paint=(color,stroke=0)=>own(new S.SKPaint({Color:S.SKColor.Parse(color),IsAntialias:true,Style:stroke?S.SKPaintStyle.Stroke:S.SKPaintStyle.Fill,StrokeWidth:stroke}));const label=(value,x,y,size=20,color='#D8E9F4')=>{const font=own(new S.SKFont(null,size));c.DrawText(String(value),x,y,font,paint(color));};const count=c.Save();try{c.Scale(w/960,h/600);fn(c,o,{own,paint,label});}finally{c.RestoreToCount(count);owned.reverse().forEach(x=>x?.Dispose());}};}
 return [
 {id:'vector_documents',group:'Documents',title:'Vector & searchable documents',tag:'PDF · XPS · Embedded fonts',description:'Export this page to retain text, glyphs, curves, gradients, and clipping in a portable document.',code:'const doc = SKDocument.CreatePdf({ Title: "Vector study" });\nconst page = doc.BeginPage(960, 600);\npage.DrawText("Searchable text", 48, 100, font, paint);\npage.DrawPath(curve, paint);\ndoc.EndPage();\nconst data = doc.ToData();\n// CreateXps uses the same drawing API.\nconsole.log(doc.RasterFallbacks);',draw:run((c,o,{own,paint,label})=>{
  label('A study in curves.',45,95,48,'#F0F6FB');label('Search this document for: SkiaSharp — café Ω',48,140,21);c.DrawLine(48,170,912,170,paint('#35485C',1));
  const p=own(new S.SKPath());p.MoveTo(55,425);p.CubicTo(200,155,320,620,470,325);p.CubicTo(640,40,760,500,900,235);c.DrawPath(p,paint('#30DEAB',5));
  for(let i=0;i<3;i++){const x=80+i*290,pp=paint(colors[i]);const sh=own(S.SKShader.CreateLinearGradient(new S.SKPoint(x,210),new S.SKPoint(x+160,335),[S.SKColor.Parse(colors[i]),S.SKColor.Parse('#153247')],[0,1],S.SKShaderTileMode.Clamp));pp.Shader=sh;c.DrawRoundRect(S.SKRect.Create(x,220,170,100),16,16,pp);}
  label('LIVE DRAWING → PORTABLE PAGE',48,520,15,'#30DEAB');label('Paths stay sharp. Text remains selectable and searchable.',48,560,21);
 })},
 {id:'document_fallbacks',group:'Documents',title:'Mixed vector & filtered graphics',tag:'Native PDF · XPS patches',description:'Text and geometry remain vector while filtered operations are rasterized at the document’s chosen DPI.',code:'const doc = SKDocument.CreatePdf({ RasterDpi: 144 });\nconst page = doc.BeginPage(960, 600);\npage.DrawText("Still searchable", 45, 80, font, paint);\npaint.ImageFilter = SKImageFilter.CreateBlur(8, 8);\npage.DrawCircle(300, 300, 100, paint);\ndoc.EndPage();\nconst bytes = doc.ToData();\nconsole.log(doc.RasterFallbacks);',draw:run((c,o,{own,paint,label})=>{label('Sharp text. Soft light.',48,100,43);label('Native PDF and managed XPS preserve their supported vector content.',48,145,20);for(let i=0;i<3;i++){const p=paint(colors[i]);p.ImageFilter=own(S.SKImageFilter.CreateBlur((o.amount??8)*(i+1)/2,(o.amount??8)*(i+1)/2));c.DrawCircle(185+i*290,320,86,p);label(['VECTOR TEXT','FILTERED LIGHT','VECTOR PAGE'][i],86+i*290,480,15);}label('Export PDF or XPS to inspect the result in a document reader.',48,555,20);})},
 {id:'drawables',group:'Canvas & resources',title:'Drawables & canvas forwarding',tag:'SKDrawable · SKNWayCanvas · SKNoDrawCanvas',description:'Draw once through a forwarding canvas, capture a reusable picture, and replay it with independent transforms.',code:'const drawable = new SKDrawable(draw, bounds);\nconst forwarding = new SKNWayCanvas(960, 600);\nforwarding.AddCanvas(canvas);\nforwarding.AddCanvas(new SKNoDrawCanvas(960, 600));\nforwarding.DrawDrawable(drawable, 100, 100);\nconst picture = drawable.Snapshot();\ncanvas.DrawPicture(picture);',draw:run((c,o,{own,paint,label})=>{const p=paint('#30DEAB',3),solid=paint('#7297FF');const draw=own(new S.SKDrawable(cc=>{cc.DrawRoundRect(S.SKRect.Create(-65,-65,130,130),18,18,p);cc.DrawCircle(0,0,34,solid);},S.SKRect.Create(-70,-70,140,140)));const no=own(new S.SKNoDrawCanvas(960,600)),fan=own(new S.SKNWayCanvas(960,600));fan.AddCanvas(c);fan.AddCanvas(no);for(let i=0;i<5;i++)fan.DrawDrawable(draw,S.SKMatrix.Concat(S.SKMatrix.CreateTranslation(110+i*185,310),S.SKMatrix.CreateRotationDegrees(i*15+(o.time??0)*15)));label('One draw callback · five independent transforms',48,90,30);label('Forwarded state is isolated; target canvases remain caller-owned.',48,545,20);})},
 {id:'gpu_capabilities',group:'GPU & compatibility',title:'Native backend capabilities',tag:'Live capability inspection',description:'Inspect the loaded engine and selected surface. Graphite availability reflects actual compiled bindings.',code:'console.log(NativeGpuCapabilities);\nconsole.log(surface.Backend, surface.RenderMode);\nconst context = surface.Context;\nif (context) console.log(context.GetResourceCacheUsage());\nconst available = SKGraphiteContext.IsBackendAvailable(\n  SKGraphiteBackend.Dawn\n);',draw:run((c,o,{paint,label})=>{label('What this engine can do',48,88,38);const cap=S.NativeGpuCapabilities??{},entries=[['Selected surface',o.surface?.Backend??'raster'],['Ganesh / WebGL bindings',cap.GaneshWebGL?'Available':'Unavailable'],['Extended native Ganesh',cap.GaneshExtended?'Available':'Needs native extension'],['Graphite / Dawn bindings',cap.GraphiteDawn?'Available':'Needs native extension'],['Skia resource cache limit',(S.SKGraphics.GetResourceCacheTotalByteLimit()/1048576).toFixed(1)+' MB'],['Registered font families',S.SKFontManager.Default.FontFamilyCount]];entries.forEach(([name,value],i)=>{const y=158+i*59;c.DrawLine(48,y+18,912,y+18,paint('#26394C',1));label(name,48,y,19,'#A8B4C5');label(value,545,y,20,colors[i%4]);});label('See the compatibility report for declaration-level status.',48,558,19);})}
 ];
}
